<div class="page-head"><div><span class="eyebrow">FINANCES</span><h1>Dépenses</h1><p class="muted">Suivez les charges de votre activité.</p></div></div><div class="content-grid"><section class="panel"><h2>Historique</h2><div class="table-wrap"><table><thead><tr><th>Libellé</th><th>Catégorie</th><th>Date</th><th>Montant</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['label']) ?></td><td><?= e($r['category']) ?></td><td><?= e(date('d/m/Y',strtotime($r['expense_date']))) ?></td><td><?= money($r['amount']) ?></td></tr><?php endforeach; ?></tbody></table></div></section><form class="panel stack" method="post" action="<?= e(url('/expenses/save')) ?>"><h2>Nouvelle dépense</h2><input type="hidden" name="_csrf" value="<?= csrf() ?>"><label>Libellé<input name="label" required></label><label>Catégorie<input name="category" placeholder="Transport, loyer, achat..."></label><label>Montant (FCFA)<input type="number" min="0" name="amount" required></label><label>Date<input type="date" name="expense_date" value="<?= date('Y-m-d') ?>"></label><label>Note<textarea name="note"></textarea></label><button class="btn primary">Enregistrer la dépense</button></form></div>